        "sourceCode": "export const meta = {\n    title: \"表头合并\",\n    description: \"通过 children 配置实现多级表头（头部合并）\",\n};\n\nimport Table from \"../../src/index.js\";\nimport type { ColumnType, Row } from \"../../src/index.js\";\nimport { makeEmployees, type Employee } from \"./_mock.js\";\n\ninterface DemoRow extends Row {\n\tdataRef: Employee & { recordNo: string }\n}\n\nconst columns: ColumnType\u003cDemoRow>[] = [\n    {\n        title: \"记录号\",\n        name: \"$.recordNo\",\n        width: 120\n    },\n    {\n        title: \"员工信息\",\n        name: \"$.employee\",\n        children: [\n            {\n                title: \"工号\",\n                name: \"$.employeeNo\",\n                width: 130\n            },\n            {\n                title: \"姓名\",\n                name: \"$.name\",\n                width: 120\n            },\n            {\n                title: \"性别\",\n                name: \"$.gender\",\n                width: 90\n            },\n            {\n                title: \"年龄\",\n                name: \"$.age\",\n                width: 90,\n                align: \"right\"\n            }\n        ]\n    },\n    {\n        title: \"联系方式\",\n        name: \"$.contact\",\n        children: [\n            {\n                title: \"电话\",\n                name: \"$.phone\",\n                width: 170\n            },\n            {\n                title: \"邮箱\",\n                name: \"$.email\",\n                width: 240\n            },\n            {\n                title: \"省份\",\n                name: \"$.province\",\n                width: 120\n            },\n            {\n                title: \"城市\",\n                name: \"$.city\",\n                width: 130\n            },\n            {\n                title: \"详细地址\",\n                name: \"$.address\",\n                width: 280\n            }\n        ]\n    },\n    {\n        title: \"岗位信息\",\n        name: \"$.position\",\n        children: [\n            {\n                title: \"公司\",\n                name: \"$.company\",\n                width: 220\n            },\n            {\n                title: \"部门\",\n                name: \"$.department\",\n                width: 150\n            },\n            {\n                title: \"职位\",\n                name: \"$.jobTitle\",\n                width: 180\n            },\n            {\n                title: \"绩效\",\n                name: \"$.performance\",\n                width: 110\n            },\n            {\n                title: \"月薪\",\n                name: \"$.salary\",\n                width: 130,\n                align: \"right\"\n            },\n            {\n                title: \"奖金\",\n                name: \"$.bonus\",\n                width: 130,\n                align: \"right\"\n            },\n            {\n                title: \"状态\",\n                name: \"$.status\",\n                width: 110\n            },\n            {\n                title: \"入职日期\",\n                name: \"$.joinDate\",\n                width: 150\n            }\n        ]\n    },\n    {\n        title: \"标签\",\n        name: \"$.tag\",\n        width: 130\n    },\n    {\n        title: \"工龄(年)\",\n        name: \"$.yearsOfService\",\n        width: 120,\n        align: \"right\"\n    }\n]\n\nconst rows: DemoRow[] = makeEmployees(2000, 20260304).map((employee, index) => ({\n    id: `${index + 1}`,\n    dataRef: {\n        ...employee,\n        recordNo: `R-${String(index + 1).padStart(5, \"0\")}`,\n    },\n}))\n\nconst MergeTableHeadersDemo = () => {\n    return (\n        \u003cTable\n            width={1250}\n            height={320}\n            columns={columns}\n            rows={rows}\n        />\n    )\n}\n\nexport default MergeTableHeadersDemo;\n",
